<?php
declare(strict_types=1);
namespace App\Infrastructure\Website;
use App\Application\Website\WebsiteStore;
use App\Application\Platform\PlatformViolation;
use Illuminate\Database\Connection;
// Author by Lab | zefry
final readonly class LaravelWebsiteStore implements WebsiteStore {
    public function __construct(private Connection $db,private array $defaults,private ?\App\Application\Notification\MailStore $mail=null,private string $publicUrl=''){}
    private function default(string $slug):array{return $this->defaults[$slug]??['id'=>['title'=>'Halaman baru','description'=>'','blocks'=>[$this->block('Halaman baru')]],'en'=>['title'=>'New page','description'=>'','blocks'=>[$this->block('New page')]]];}
    private function block(string $title):array{return ['id'=>'intro','type'=>'text','tone'=>'light','eyebrow'=>'','title'=>$title,'body'=>'','image'=>'','alt'=>'','button'=>'','href'=>'/register','items'=>[]];}
    public function draft(string $slug):array{$row=$this->db->table('oneqay_site_pages')->where('slug',$slug)->first();return ['slug'=>$slug,'version'=>(int)($row->version??0),'published_revision'=>$row->published_revision??null,'document'=>$row===null?$this->default($slug):json_decode($row->draft,true,64,JSON_THROW_ON_ERROR)];}
    public function published(string $slug):?array{$page=$this->db->table('oneqay_site_pages')->where('slug',$slug)->first();if(($page->published_revision??null)===null)return $this->defaults[$slug]??null;$raw=$this->db->table('oneqay_site_revisions')->where('slug',$slug)->where('id',$page->published_revision)->value('document');return $raw===null?null:json_decode($raw,true,64,JSON_THROW_ON_ERROR);}
    public function listing():array{$pages=$this->db->table('oneqay_site_pages')->get(['slug','version','published_revision','updated_at'])->keyBy('slug');$out=[];foreach(array_unique([...array_keys($this->defaults),...$pages->keys()->all()])as$slug){$p=$pages->get($slug);$out[]=['slug'=>$slug,'version'=>(int)($p->version??0),'published'=>($p->published_revision??null)!==null||isset($this->defaults[$slug])];}return $out;}
    public function save(string $slug,int $version,array $document):array{$row=$this->db->table('oneqay_site_pages')->where('slug',$slug)->lockForUpdate()->first();if((int)($row->version??0)!==$version)throw new PlatformViolation('STALE_VERSION',409);if($row===null&&$this->db->table('oneqay_site_pages')->count()>=100)throw new PlatformViolation('PAGE_LIMIT',422);$change=['version'=>$version+1,'draft'=>json_encode($document,JSON_THROW_ON_ERROR),'updated_at'=>time()];if($row===null)$this->db->table('oneqay_site_pages')->insert(['slug'=>$slug,'published_revision'=>null]+$change);else $this->db->table('oneqay_site_pages')->where('slug',$slug)->update($change);return $this->draft($slug);}
    public function publish(string $slug,int $version,string $digest,string $actor):array{$p=$this->draft($slug);if($version!==$p['version']||$version===0)throw new PlatformViolation('STALE_VERSION',409);$json=json_encode($p['document'],JSON_THROW_ON_ERROR);if(!hash_equals(hash('sha256',$json),$digest))throw new PlatformViolation('PREVIEW_REQUIRED',409);$id=bin2hex(random_bytes(16));$this->db->table('oneqay_site_revisions')->insert(['id'=>$id,'slug'=>$slug,'document'=>$json,'actor'=>$actor,'created_at'=>time()]);$this->db->table('oneqay_site_pages')->where('slug',$slug)->update(['published_revision'=>$id,'version'=>$version+1,'updated_at'=>time()]);return ['slug'=>$slug,'version'=>$version+1,'revision'=>$id];}
    public function revisions(string $slug):array{return $this->db->table('oneqay_site_revisions')->where('slug',$slug)->orderByDesc('created_at')->orderByDesc('id')->limit(20)->get(['id','created_at','actor'])->map(fn($r)=>(array)$r)->all();}
    public function restore(string $slug,int $version,string $revision):array{$json=$this->db->table('oneqay_site_revisions')->where('slug',$slug)->where('id',$revision)->value('document');if($json===null)throw new PlatformViolation('REVISION_NOT_FOUND',404);return $this->save($slug,$version,json_decode($json,true,64,JSON_THROW_ON_ERROR));}
    public function putMedia(string $id,string $mime,string $bytes,string $actor):void{if($this->hasMedia($id))return;if($this->db->table('oneqay_site_media')->sum('bytes')+strlen($bytes)>100*1024*1024)throw new PlatformViolation('MEDIA_STORAGE_LIMIT',413);$this->db->table('oneqay_site_media')->insert(['id'=>$id,'mime'=>$mime,'bytes'=>strlen($bytes),'payload'=>base64_encode($bytes),'actor'=>$actor,'created_at'=>time()]);}
    public function hasMedia(string $id):bool{return $this->db->table('oneqay_site_media')->where('id',$id)->exists();}
    public function media(string $id,bool $preview):?array{if(!$preview){$used=false;foreach($this->db->table('oneqay_site_pages')->whereNotNull('published_revision')->cursor()as$p){$doc=$this->published($p->slug);foreach(['id','en']as$l)foreach($doc[$l]['blocks']??[]as$b)if(($b['image']??'')===$id)$used=true;}if(!$used)return null;}$r=$this->db->table('oneqay_site_media')->where('id',$id)->first();return $r===null?null:['mime'=>$r->mime,'bytes'=>base64_decode($r->payload,true)];}
    public function registration(array $input):void{if($this->db->getSchemaBuilder()->hasTable('oneqay_platform_control_settings')){$settings=json_decode((string)$this->db->table('oneqay_platform_control_settings')->where('id',1)->value('configuration'),true,32,JSON_THROW_ON_ERROR);if(($settings['registration_enabled']??true)!==true)throw new PlatformViolation('REGISTRATION_PAUSED',409);}$email=strtolower($input['email']);$hash=hash('sha256',$email);if($this->db->table('oneqay_platform_businesses')->where('email',$email)->exists()||$this->db->table('oneqay_site_registrations')->where('email_hash',$hash)->exists())return;$id=bin2hex(random_bytes(16));$now=time();$b=['id'=>$id,'name'=>$input['name'],'email'=>$email,'locale'=>$input['locale'],'status'=>'invited','version'=>1,'created_at'=>$now,'updated_at'=>$now];foreach(['tenant'=>'business','identity'=>'owner','organization'=>'org','outlet'=>'outlet','device'=>'device']as$key=>$prefix)$b[$key.'_id']=$prefix.'-'.bin2hex(random_bytes(12));$token=bin2hex(random_bytes(32));$b+=['token_hash'=>hash('sha256',$token),'token_expires_at'=>$now+86400];
      if($this->mail===null||!str_starts_with($this->publicUrl,'https://'))throw new PlatformViolation('REGISTRATION_MAIL_UNAVAILABLE',503);
      $this->db->table('oneqay_platform_businesses')->insert($b);
      $url=rtrim($this->publicUrl,'/').'/activate-business#token='.$token;
      $subject=$input['locale']==='id'?'Verifikasi email bisnis oneQay':'Verify your oneQay business email';
      $body=$input['locale']==='id'?"Halo pemilik {$b['name']},\n\nSatu langkah lagi untuk memakai oneQay secara gratis. Verifikasi email dan buat kata sandi melalui tautan berikut (berlaku 24 jam):\n$url\n\nSetelah verifikasi, akun admin bisnis langsung aktif tanpa persetujuan manual. Jangan bagikan tautan ini. Jika Anda tidak mendaftar, abaikan email ini.\nCopyright oneQay":"Hello {$b['name']} owner,\n\nStart using oneQay for free. Verify your email and set your password using this link (valid for 24 hours):\n$url\n\nYour business admin account activates after verification, without manual approval. Do not share this link. Ignore this email if you did not register.\nCopyright oneQay";
      $this->mail->enqueue($b['tenant_id'],'registration-verify-'.$id,$email,$subject,$body,$now);
      if($this->db->getSchemaBuilder()->hasTable('oneqay_platform_marketing_preferences'))$this->db->table('oneqay_platform_marketing_preferences')->insert(['business_id'=>$id,'subscribed'=>($input['marketing_consent']??false)===true,'source'=>'registration-checkbox-v1','updated_at'=>$now]);$this->db->table('oneqay_site_registrations')->insert(['email_hash'=>$hash,'business_id'=>$id,'phone'=>$input['phone'],'business_type'=>$input['business_type'],'consent_version'=>'terms-2026-10-20','created_at'=>$now]);$this->db->table('oneqay_platform_audit')->insert(['actor'=>'public-registration','action'=>'registration','business_id'=>$id,'reason'=>'Email verification queued; accepted terms-2026-10-20; free service','occurred_at'=>$now]);}
    public function resendVerification(string $email):void {
      $row=$this->db->table('oneqay_platform_businesses as b')->join('oneqay_site_registrations as r','r.business_id','=','b.id')->where('b.email',$email)->lockForUpdate()->first(['b.*']);
      if(!$row||!in_array($row->status,['pending','invited'],true))return;
      if($this->mail===null||!str_starts_with($this->publicUrl,'https://'))throw new PlatformViolation('REGISTRATION_MAIL_UNAVAILABLE',503);
      $token=bin2hex(random_bytes(32));$now=time();$url=rtrim($this->publicUrl,'/').'/activate-business#token='.$token;
      $this->db->table('oneqay_platform_businesses')->where('id',$row->id)->where('version',$row->version)->update(['status'=>'invited','version'=>$row->version+1,'token_hash'=>hash('sha256',$token),'token_expires_at'=>$now+86400,'updated_at'=>$now]);
      $this->db->table('oneqay_site_registrations')->where('business_id',$row->id)->update(['consent_version'=>'terms-2026-10-20']);
      $body=$row->locale==='id'?"Tautan verifikasi oneQay yang baru (24 jam):\n$url\nBuat kata sandi untuk langsung mengaktifkan akun. Tautan sebelumnya tidak berlaku. Abaikan jika Anda tidak meminta.\nCopyright oneQay":"Your new oneQay verification link (24 hours):\n$url\nSet your password to activate automatically. Previous links are invalid. Ignore if you did not request this.\nCopyright oneQay";
      $this->mail->enqueue($row->tenant_id,'verification-resend-'.$row->id.'-'.($row->version+1),$email,'oneQay · Email verification',$body,$now);
      $this->db->table('oneqay_platform_audit')->insert(['actor'=>'public-registration','action'=>'verification.resend','business_id'=>$row->id,'reason'=>'Verification token rotated; accepted terms-2026-10-20','occurred_at'=>$now]);
    }
    public function registrationDetails(array $ids):array {if(!$this->db->getSchemaBuilder()->hasTable('oneqay_site_registrations'))return [];return $this->db->table('oneqay_site_registrations')->whereIn('business_id',$ids)->get(['business_id','phone','business_type','created_at'])->keyBy('business_id')->map(fn($r)=>(array)$r)->all();}
}
